function validate([replacements, text]) {
  if (replacements.length < 1 || replacements.length > 10) return 'replacements needs 1 to 10 pairs.';
  const values = new Map();
  for (const pair of replacements) {
    if (pair.length !== 2) return 'Each replacement is a [key, value] pair.';
    const [key, value] = pair;
    if (!/^[A-Z]$/.test(key)) return 'Each key is a single uppercase letter.';
    if (values.has(key)) return 'Each key appears in only one pair.';
    if (value.length < 1 || value.length > 8) return 'Each value has 1 to 8 characters.';
    if (!/^([a-z]|%[A-Z]%)+$/.test(value)) return 'A value holds lowercase letters and %X% placeholders only.';
    values.set(key, value);
  }
  const mentions = value => (value.match(/%[A-Z]%/g) || []).map(placeholder => placeholder[1]);
  for (const value of values.values()) if (mentions(value).some(key => !values.has(key))) return 'Every placeholder must name a key of replacements.';
  const parts = text.split('_');
  if (text.length !== 4 * values.size - 1 || parts.length !== values.size || new Set(parts).size !== parts.length || parts.some(part => !/^%[A-Z]%$/.test(part) || !values.has(part[1]))) return 'text lists the placeholder of every key once, joined by underscores.';
  // A depth-first search that meets a key still in progress has found a cycle.
  const state = new Map();
  const cyclic = key => {
    if (state.get(key) === 'done') return false;
    if (state.get(key) === 'open') return true;
    state.set(key, 'open');
    if (mentions(values.get(key)).some(cyclic)) return true;
    state.set(key, 'done');
    return false;
  };
  if ([...values.keys()].some(cyclic)) return 'No key may depend on itself.';
  return null;
}

