function applySubstitutions(replacements, text) {
  const values = new Map(replacements);
  const done = new Map();
  function expand(s) {
    let result = '';
    let i = 0;
    while (i < s.length) {
      if (s[i] === '%') {
        const end = s.indexOf('%', i + 1);
        const key = s.slice(i + 1, end);
        if (!done.has(key)) {
          done.set(key, expand(values.get(key)));
        }
        result += done.get(key);
        i = end + 1;
      } else {
        result += s[i];
        i++;
      }
    }
    return result;
  }
  return expand(text);
}

