function applySubstitutions(replacements, text) {
  // Replace the first placeholder by its raw value, again and again, until none is left.
  const values = new Map(replacements);
  let current = text;
  for (;;) {
    const start = current.indexOf('%');
    if (start === -1) return current;
    const end = current.indexOf('%', start + 1);
    current = current.slice(0, start) + values.get(current.slice(start + 1, end)) + current.slice(end + 1);
  }
}

