function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = int(0, i);
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const keys = shuffle('ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('')).slice(0, size === 'large' ? 10 : int(1, 5));
  // A key only mentions keys listed after it, so there is no cycle. Large inputs mostly mention the next one or two
  // keys, so the placeholders nest deeply and the answer grows long.
  const nest = size === 'large' ? 0.85 : rand();
  const stop = size === 'large' ? 0.1 : 0.35;
  const replacements = keys.map((key, index) => {
    let value = '';
    while (value.length < 8) {
      const last = size === 'large' ? Math.min(index + 2, keys.length - 1) : keys.length - 1;
      if (index < keys.length - 1 && value.length <= 5 && rand() < nest) value += `%${keys[int(index + 1, last)]}%`;
      else value += letters[int(0, 25)];
      if (rand() < stop) break;
    }
    return [key, value];
  });
  // Neither the pairs nor the text follow the dependency order.
  const text = shuffle(keys.slice()).map(key => `%${key}%`).join('_');
  return [shuffle(replacements), text];
}
